        cJSON_free(schema_json);
        if (rc != CADDONS_OK) return rc;
        descriptor.origin = CADDONS_TOOL_MCP;
        descriptor.risk = policy->risk;
        descriptor.timeout_ms = policy->timeout_ms ? policy->timeout_ms
